<?php
if(PHP_SAPI!=='cli'){http_response_code(403);exit("CLI only\n");}$root=dirname(__DIR__,2);require_once $root.'/config.php';require_once $root.'/base/NotificationPolicy.class.php';require_once $root.'/base/WormholePolicy.class.php';$db=new mysqli($conf['db_server'],$conf['db_username'],$conf['db_password'],$conf['db_name']);if($db->connect_error){fwrite(STDERR,"DB connect error: ".$db->connect_error."\n");exit(1);}$db->set_charset('utf8mb4');$db->query("CREATE TABLE IF NOT EXISTS wormhole_expeditions(expedition_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,signature_id BIGINT UNSIGNED NOT NULL,uid INT NOT NULL,scan_strength INT UNSIGNED NOT NULL,dark_matter_cost BIGINT UNSIGNED NOT NULL,status VARCHAR(16) NOT NULL DEFAULT 'enroute',dispatched_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,resolves_at DATETIME NOT NULL,outcome VARCHAR(40) NULL,reward_dark_matter BIGINT UNSIGNED NOT NULL DEFAULT 0,reward_exotic_matter BIGINT UNSIGNED NOT NULL DEFAULT 0,reward_tritanium BIGINT UNSIGNED NOT NULL DEFAULT 0,resolved_at DATETIME NULL,PRIMARY KEY(expedition_id),KEY idx_wormhole_due(status,resolves_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");$db->query("CREATE TABLE IF NOT EXISTS wormhole_signatures(signature_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,uid INT NOT NULL,signature_code VARCHAR(24) NOT NULL,wormhole_class VARCHAR(20) NOT NULL,scan_difficulty INT UNSIGNED NOT NULL DEFAULT 25,stability INT UNSIGNED NOT NULL DEFAULT 50,status VARCHAR(16) NOT NULL DEFAULT 'detected',discovered_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,expires_at DATETIME NOT NULL,PRIMARY KEY(signature_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");NotificationPolicy::ensureTable($db);$db->query("ALTER TABLE wormhole_expeditions ADD COLUMN IF NOT EXISTS stability_at_dispatch INT UNSIGNED NOT NULL DEFAULT 50, ADD COLUMN IF NOT EXISTS elapsed_minutes INT UNSIGNED NOT NULL DEFAULT 0, ADD COLUMN IF NOT EXISTS collapse_risk INT UNSIGNED NOT NULL DEFAULT 0, ADD COLUMN IF NOT EXISTS exotic_tier INT UNSIGNED NOT NULL DEFAULT 1");$rows=$db->query("SELECT e.*,s.signature_code,s.wormhole_class,s.scan_difficulty FROM wormhole_expeditions e JOIN wormhole_signatures s ON s.signature_id=e.signature_id WHERE e.status='enroute' AND e.resolves_at<=NOW() ORDER BY e.expedition_id ASC LIMIT 250");$resolved=0;$failed=0;if($rows)while($e=$rows->fetch_assoc()){$id=(int)$e['expedition_id'];$uid=(int)$e['uid'];$strength=(int)$e['scan_strength'];$difficulty=(int)$e['scan_difficulty'];$dispatched=strtotime((string)$e['dispatched_at'])?:time();$elapsed=max((int)($e['elapsed_minutes']??1),(int)floor(max(0,time()-$dispatched)/60));$stability=(int)($e['stability_at_dispatch']??50);$risk=WormholePolicy::collapseRisk($stability,$difficulty,(string)$e['wormhole_class'],$elapsed);$tier=max((int)($e['exotic_tier']??1),WormholePolicy::exoticTier($difficulty,$risk));$collapse=WormholePolicy::collapse($risk);$success=!$collapse&&random_int(1,100)<=max(10,min(95,50+$strength-$difficulty));$dm=$success?random_int(80,160)+($difficulty*4)+($tier*20):0;$exotic=$success?WormholePolicy::exoticReward($tier,$difficulty):0;$trit=$success?random_int(20,110)+$difficulty+($tier*15):0;$outcome=$success?'charted_corridor_tier_'.$tier:'collapsed_signature';$status=$success?'resolved':'failed';$db->begin_transaction();$lock=$db->query("SELECT expedition_id FROM wormhole_expeditions WHERE expedition_id=$id AND status='enroute' FOR UPDATE");if(!$lock||!$lock->num_rows){$db->rollback();continue;}$ok=$db->query("UPDATE wormhole_expeditions SET status='$status',outcome='$outcome',elapsed_minutes=$elapsed,collapse_risk=$risk,exotic_tier=$tier,reward_dark_matter=$dm,reward_exotic_matter=$exotic,reward_tritanium=$trit,resolved_at=NOW() WHERE expedition_id=$id AND status='enroute' LIMIT 1");if($ok&&$success)$ok=$db->query("UPDATE player_resources SET dark_matter=dark_matter+$dm,exotic_matter=exotic_matter+$exotic,tritanium=tritanium+$trit WHERE uid=$uid LIMIT 1");$safeCode=$db->real_escape_string((string)$e['signature_code']);$db->query("UPDATE wormhole_signatures SET status='explored' WHERE signature_id=".(int)$e['signature_id']);if($ok){NotificationPolicy::push($db,$uid,'wormhole_expedition',$success?'Wormhole corridor charted':'Wormhole collapsed',$success?'Probe returned from '.$safeCode.' after '.$elapsed.' minutes at '.$risk.'% collapse risk with Tier '.$tier.' rewards: '.$dm.' Dark Matter, '.$exotic.' Exotic Matter, and '.$trit.' Tritanium.':'Probe lost when '.$safeCode.' collapsed after '.$elapsed.' minutes at '.$risk.'% risk; no reward recovered.','wormhole:resolve:'.$id,['outcome'=>$outcome,'dark_matter'=>$dm,'exotic_matter'=>$exotic,'tritanium'=>$trit]);$db->commit();$resolved++;if(!$success)$failed++;}else{$db->rollback();}}echo "wormhole_tick resolved=$resolved failed=$failed\n";
?>
